/* Booster AI: six prepared Lady voice recordings. No live AI or microphone connection. */
(() => {
  const ITEMS = [{"id":"welcome","question":"من أنتم؟","text":"حيّاك الله في بوستر. إحنا شركة سعودية نساعد المنشآت تستفيد من الذكاء الاصطناعي في شغلها اليومي.","seconds":8.64,"audio":"data:audio/mpeg;base64,"},{"id":"purpose","question":"وش هدفكم؟","text":"هدفنا نخلي شغلكم أسهل وأوضح. نقلّل المهام المتكررة، ونساعد فريقكم يركّز على الشغل اللي يضيف قيمة.","seconds":8.8,"audio":"data:audio/mpeg;base64,"},{"id":"help","question":"كيف تساعدوننا؟","text":"نقدر نبني لكم مساعدين أذكياء، ونربط الأنظمة، ونرتّب سير العمل في المبيعات وخدمة العملاء وباقي الأقسام.","seconds":8.0,"audio":"data:audio/mpeg;base64,"},{"id":"example","question":"عطيني مثال","text":"مثلاً، إذا تتكرر عليكم أسئلة العملاء في الواتساب، نقدر نبني مساعد يجاوب من معلوماتكم، ويحوّل الحالات اللي تحتاج موظف لفريقكم.","seconds":10.56,"audio":"data:audio/mpeg;base64,"},{"id":"approach","question":"وش يميّز طريقتكم؟","text":"نبدأ نفهم طريقة شغلكم واحتياجكم، وبعدها نبني الحل المناسب، وندرّب فريقكم عليه ونحسّنه معكم.","seconds":8.0,"audio":"data:audio/mpeg;base64,"},{"id":"start","question":"كيف نبدأ؟","text":"البداية بسيطة. اتركوا لنا رسالة من صفحة التواصل، وقولوا لنا وش أكثر شغلة تأخذ من وقتكم، ونشوف معكم الحل المناسب.","seconds":9.28,"audio":"data:audio/mpeg;base64,"}];
  function mount() {
    if (document.getElementById('booster-voice-guide')) return;
    const style=document.createElement('style');
    style.textContent=`
      .bv-guide{position:fixed;right:20px;bottom:20px;z-index:60;width:min(370px,calc(100vw - 28px));direction:rtl;font-family:inherit;color:#f4f7ff}
      .bv-panel{padding:20px;background:#071747;border:1px solid #226b70;border-radius:22px;box-shadow:0 16px 55px #0005;margin-bottom:10px;max-height:calc(100dvh - 100px);overflow:auto}
      .bv-guide [hidden]{display:none!important}.bv-top{display:flex;align-items:start;justify-content:space-between;gap:16px}.bv-eyebrow{margin:0 0 5px;color:#56ddbd;font-size:12px}.bv-guide h2{margin:0;font-size:23px}.bv-close{background:none;border:0;color:#c7d7e9;font-size:25px;cursor:pointer;padding:0 6px}.bv-subtitle{font-size:13px;color:#bbc9df;margin:10px 0 16px;line-height:1.6}
      .bv-questions{display:grid;grid-template-columns:1fr 1fr;gap:8px}.bv-question{font:inherit;font-size:13px;min-height:45px;padding:9px;border:1px solid #344767;border-radius:12px;background:#102451;color:#f4f7ff;cursor:pointer;text-align:right}.bv-question:hover,.bv-question[aria-pressed=true]{background:#153e54;border-color:#41d2ae;color:#a7f5da}.bv-guide button:focus-visible,.bv-guide a:focus-visible{outline:3px solid #b9f2e0;outline-offset:3px}
      .bv-answer{margin-top:16px;padding-top:14px;border-top:1px solid #293f61}.bv-title{margin:0 0 6px;color:#56ddbd;font-size:13px}.bv-text{font-size:15px;line-height:1.8;margin:0;min-height:70px}.bv-status{font-size:12px;color:#bdcde2;min-height:19px;margin:8px 0}.bv-actions{display:flex;gap:8px;align-items:center}.bv-control,.bv-contact{font:inherit;font-size:13px;padding:10px 14px;border-radius:10px;text-decoration:none;cursor:pointer}.bv-control{border:1px solid #435573;background:transparent;color:#f4f7ff}.bv-contact{background:#15c69c;color:#062431;border:1px solid #15c69c}.bv-launch{font:inherit;background:#15c69c;color:#062431;border:0;border-radius:30px;padding:14px 21px;font-weight:700;cursor:pointer;box-shadow:0 8px 25px #0003;float:right}.bv-footer{font-size:11px;color:#9fb1cb;margin:14px 0 0}
      @media(max-width:480px){.bv-guide{right:14px;bottom:14px}.bv-panel{padding:16px}.bv-guide h2{font-size:21px}}
    `;
    document.head.append(style);
    const root=document.createElement('aside');root.id='booster-voice-guide';root.className='bv-guide';root.setAttribute('aria-label','دليل بوستر الصوتي');
    root.innerHTML=`<section class="bv-panel" id="bv-panel" aria-labelledby="bv-heading" hidden>
      <div class="bv-top"><div><p class="bv-eyebrow">نشخّص. نبني. نعزّز.</p><h2 id="bv-heading">تعرّف على بوستر</h2></div><button class="bv-close" aria-label="إغلاق الدليل">×</button></div>
      <p class="bv-subtitle">اختر سؤالك واسمع الإجابة بصوت سعودي.</p>
      <div class="bv-questions" aria-label="أسئلة عن بوستر"></div>
      <div class="bv-answer"><p class="bv-title"></p><p class="bv-text"></p><p class="bv-status" aria-live="polite"></p>
      <div class="bv-actions"><button class="bv-control" type="button">أعد الاستماع</button><a class="bv-contact" href="contact.html">خلّنا نتواصل</a></div></div>
      <p class="bv-footer">ست إجابات قصيرة عن شركتنا وطريقة عملنا.</p>
    </section><button class="bv-launch" id="voice-demo-btn" type="button" aria-expanded="false" aria-controls="bv-panel">اسمع عن بوستر ◀</button>`;
    document.body.append(root);
    const panel=root.querySelector('.bv-panel'),launch=root.querySelector('.bv-launch'),status=root.querySelector('.bv-status'),control=root.querySelector('.bv-control');
    const audio=new Audio();audio.preload='auto';
    let selected=0,playing=false,token=0;
    const buttons=ITEMS.map((item,index)=>{
      const button=document.createElement('button');button.type='button';button.className='bv-question';button.textContent=item.question;button.setAttribute('aria-pressed','false');
      button.addEventListener('click',()=>play(index));root.querySelector('.bv-questions').append(button);return button;
    });
    function stop(){token++;audio.pause();audio.currentTime=0;playing=false;control.textContent='أعد الاستماع';}
    function show(index){selected=index;root.querySelector('.bv-title').textContent=ITEMS[index].question;root.querySelector('.bv-text').textContent=ITEMS[index].text;buttons.forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));}
    async function play(index){
      stop();const request=token;show(index);status.textContent='جارٍ التشغيل…';
      audio.src=ITEMS[index].audio;
      try{await audio.play();if(request!==token)return;playing=true;control.textContent='إيقاف الصوت';status.textContent='تستمع الآن';}
      catch(error){if(request!==token)return;status.textContent='اضغط «أعد الاستماع» لتشغيل الصوت.';}
    }
    audio.addEventListener('ended',()=>{playing=false;control.textContent='أعد الاستماع';status.textContent='اختر سؤالاً آخر أو تواصل معنا.';});
    audio.addEventListener('error',()=>{playing=false;control.textContent='أعد الاستماع';status.textContent='تعذر تشغيل الصوت. تقدر تقرأ الإجابة هنا.';});
    control.addEventListener('click',()=>{if(playing){stop();status.textContent='تم إيقاف الصوت';}else play(selected);});
    function close(){stop();panel.hidden=true;launch.setAttribute('aria-expanded','false');launch.focus();}
    root.querySelector('.bv-close').addEventListener('click',close);
    launch.addEventListener('click',()=>{if(!panel.hidden){close();return;}panel.hidden=false;launch.setAttribute('aria-expanded','true');play(0);});
    root.addEventListener('keydown',event=>{if(event.key==='Escape'&&!panel.hidden){close();event.preventDefault();}});
    document.addEventListener('visibilitychange',()=>{if(document.hidden){stop();status.textContent='اضغط «أعد الاستماع» للمتابعة.';}});
    show(0);
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount,{once:true});else mount();
})();
